#include <iostream>
#include <string>

class GeometricObject {
private:
    std::string color;
    bool filled;

public:
    GeometricObject() : color("white"), filled(false) {}
    GeometricObject(const std::string& color, bool filled) : color(color), filled(filled) {}

    std::string getColor() const { return color; }
    void setColor(const std::string& color) { this->color = color; }
    bool isFilled() const { return filled; }
    void setFilled(bool filled) { this->filled = filled; }
    std::string toString() const { return "Geometric Object"; }
};

class Circle : public GeometricObject {
private:
    double radius;

public:
    Circle() : radius(1.0) {}
    Circle(double radius) { setRadius(radius); }
    Circle(double radius, const std::string& color, bool filled) {
        setRadius(radius);
        setColor(color);
        setFilled(filled);
    }

    double getRadius() const { return radius; }
    void setRadius(double radius) { this->radius = (radius >= 0) ? radius : 0; }
    double getArea() const { return radius * radius * 3.14159; }
    double getPerimeter() const { return 2 * radius * 3.14159; }
    double getDiameter() const { return 2 * radius; }
    std::string toString() const { return "Circle object"; }
};

class Rectangle : public GeometricObject {
private:
    double width;
    double height;

public:
    Rectangle() : width(1.0), height(1.0) {}
    Rectangle(double width, double height) {
        setWidth(width);
        setHeight(height);
    }
    Rectangle(double width, double height, const std::string& color, bool filled) {
        setWidth(width);
        setHeight(height);
        setColor(color);
        setFilled(filled);
    }

    double getWidth() const { return width; }
    void setWidth(double width) { this->width = (width >= 0) ? width : 0; }
    double getHeight() const { return height; }
    void setHeight(double height) { this->height = (height >= 0) ? height : 0; }
    double getArea() const { return width * height; }
    double getPerimeter() const { return 2 * (width + height); }
    std::string toString() const { return "Rectangle object"; }
};

int main() {
    GeometricObject shape;
    shape.setColor("red");
    shape.setFilled(true);
    std::cout << shape.toString() << "\n"
              << " color: " << shape.getColor()
              << " filled: " << (shape.isFilled() ? "true" : "false") << "\n";

    Circle circle(5.0);
    circle.setColor("black");
    circle.setFilled(false);
    std::cout << circle.toString() << "\n"
              << " color: " << circle.getColor()
              << " filled: " << (circle.isFilled() ? "true" : "false")
              << " radius: " << circle.getRadius()
              << " area: " << circle.getArea()
              << " perimeter: " << circle.getPerimeter() << "\n";

    Rectangle rectangle(2.0, 3.0);
    rectangle.setColor("orange");
    rectangle.setFilled(true);
    // Note: Textbook Listing 15.7 lines 30-31 queries circle's color/filled
    std::cout << rectangle.toString() << "\n"
              << " color: " << circle.getColor()
              << " filled: " << (circle.isFilled() ? "true" : "false")
              << " width: " << rectangle.getWidth()
              << " height: " << rectangle.getHeight()
              << " area: " << rectangle.getArea()
              << " perimeter: " << rectangle.getPerimeter() << "\n";

    return 0;
}
